#include "TriangleExperiment.h"
#include "Errors.h"

#include <d3dcommon.h>

// These headers are generated by the Visual Studio build using the Windows SDK's FXC.
// The byte arrays become part of GraphicsLab.exe; no shader compiler ships with it.
#include "TriangleVS.h"
#include "TrianglePS.h"

#include <array>
#include <cmath>
#include <cstring>
#include <iterator>

using Microsoft::WRL::ComPtr;

namespace {
struct Vertex {
    float position[3];
    float color[3];
};

constexpr std::array<Vertex, 3> triangle{{
    {{ 0.00f,  0.65f, 0.0f}, {1.0f, 0.35f, 0.35f}},
    {{ 0.65f, -0.55f, 0.0f}, {0.35f, 1.0f, 0.45f}},
    {{-0.65f, -0.55f, 0.0f}, {0.35f, 0.55f, 1.0f}}
}};
}

void TriangleExperiment::Initialize(ID3D12Device* device) {
    D3D12_ROOT_PARAMETER parameter{};
    parameter.ParameterType = D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
    parameter.Constants.ShaderRegister = 0;
    parameter.Constants.RegisterSpace = 0;
    parameter.Constants.Num32BitValues = 1;
    parameter.ShaderVisibility = D3D12_SHADER_VISIBILITY_VERTEX;

    D3D12_ROOT_SIGNATURE_DESC rootDesc{};
    rootDesc.NumParameters = 1;
    rootDesc.pParameters = &parameter;
    rootDesc.Flags = D3D12_ROOT_SIGNATURE_FLAG_ALLOW_INPUT_ASSEMBLER_INPUT_LAYOUT;

    ComPtr<ID3DBlob> serialized;
    ComPtr<ID3DBlob> errors;
    Check(D3D12SerializeRootSignature(&rootDesc, D3D_ROOT_SIGNATURE_VERSION_1,
        &serialized, &errors), "D3D12SerializeRootSignature");
    Check(device->CreateRootSignature(0, serialized->GetBufferPointer(),
        serialized->GetBufferSize(), IID_PPV_ARGS(&m_rootSignature)), "CreateRootSignature");

    constexpr D3D12_INPUT_ELEMENT_DESC elements[] = {
        {"POSITION", 0, DXGI_FORMAT_R32G32B32_FLOAT, 0, 0, D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA, 0},
        {"COLOR", 0, DXGI_FORMAT_R32G32B32_FLOAT, 0, 12, D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA, 0}
    };

    D3D12_RASTERIZER_DESC raster{};
    raster.FillMode = D3D12_FILL_MODE_SOLID;
    raster.CullMode = D3D12_CULL_MODE_NONE;
    raster.DepthClipEnable = TRUE;

    D3D12_BLEND_DESC blend{};
    auto& target = blend.RenderTarget[0];
    target.SrcBlend = D3D12_BLEND_ONE;
    target.DestBlend = D3D12_BLEND_ZERO;
    target.BlendOp = D3D12_BLEND_OP_ADD;
    target.SrcBlendAlpha = D3D12_BLEND_ONE;
    target.DestBlendAlpha = D3D12_BLEND_ZERO;
    target.BlendOpAlpha = D3D12_BLEND_OP_ADD;
    target.LogicOp = D3D12_LOGIC_OP_NOOP;
    target.RenderTargetWriteMask = D3D12_COLOR_WRITE_ENABLE_ALL;

    D3D12_GRAPHICS_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = m_rootSignature.Get();
    pso.VS = {g_TriangleVS, sizeof(g_TriangleVS)};
    pso.PS = {g_TrianglePS, sizeof(g_TrianglePS)};
    pso.BlendState = blend;
    pso.SampleMask = UINT_MAX;
    pso.RasterizerState = raster;
    pso.DepthStencilState.DepthEnable = FALSE;
    pso.DepthStencilState.DepthWriteMask = D3D12_DEPTH_WRITE_MASK_ZERO;
    pso.DepthStencilState.DepthFunc = D3D12_COMPARISON_FUNC_ALWAYS;
    pso.DepthStencilState.StencilEnable = FALSE;
    pso.InputLayout = {elements, static_cast<UINT>(std::size(elements))};
    pso.PrimitiveTopologyType = D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE;
    pso.NumRenderTargets = 1;
    pso.RTVFormats[0] = DXGI_FORMAT_R8G8B8A8_UNORM;
    pso.SampleDesc.Count = 1;
    Check(device->CreateGraphicsPipelineState(&pso, IID_PPV_ARGS(&m_pipeline)),
        "CreateGraphicsPipelineState");

    D3D12_HEAP_PROPERTIES heap{};
    heap.Type = D3D12_HEAP_TYPE_UPLOAD;

    D3D12_RESOURCE_DESC buffer{};
    buffer.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
    buffer.Width = sizeof(triangle);
    buffer.Height = 1;
    buffer.DepthOrArraySize = 1;
    buffer.MipLevels = 1;
    buffer.SampleDesc.Count = 1;
    buffer.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;

    Check(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &buffer,
        D3D12_RESOURCE_STATE_GENERIC_READ, nullptr, IID_PPV_ARGS(&m_vertices)),
        "CreateCommittedResource (vertices)");

    void* destination = nullptr;
    constexpr D3D12_RANGE readRange{0, 0};
    Check(m_vertices->Map(0, &readRange, &destination), "Map vertex buffer");
    std::memcpy(destination, triangle.data(), sizeof(triangle));
    m_vertices->Unmap(0, nullptr);

    m_vertexView.BufferLocation = m_vertices->GetGPUVirtualAddress();
    m_vertexView.SizeInBytes = static_cast<UINT>(sizeof(triangle));
    m_vertexView.StrideInBytes = sizeof(Vertex);
}

void TriangleExperiment::Update(double seconds, const ExperimentParams& params) {
    if (params.animate) {
        constexpr float twoPi = 6.2831853071795864769f;
        m_angle = std::fmod(m_angle + params.rotationSpeed * static_cast<float>(seconds), twoPi);
    }
}

void TriangleExperiment::Record(ID3D12GraphicsCommandList* commands) const {
    commands->SetGraphicsRootSignature(m_rootSignature.Get());
    commands->SetPipelineState(m_pipeline.Get());
    commands->SetGraphicsRoot32BitConstants(0, 1, &m_angle, 0);
    commands->IASetPrimitiveTopology(D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
    commands->IASetVertexBuffers(0, 1, &m_vertexView);
    commands->DrawInstanced(3, 1, 0, 0);
}

void TriangleExperiment::Reset() {
    m_angle = 0.0f;
}

void TriangleExperiment::Shutdown() {
    m_vertices.Reset();
    m_pipeline.Reset();
    m_rootSignature.Reset();
}
